-- Idempotent PostgreSQL script for Discount Management Module
-- Run manually against pos_db; never invoked at application startup.
BEGIN;
SET LOCAL lock_timeout = '10s';

DO $$
BEGIN
    IF current_database() <> 'pos_db' THEN
        RAISE EXCEPTION 'DiscountModule.sql must run against pos_db';
    END IF;
END $$;

-- 1. DiscountTypes Lookup Table
CREATE TABLE IF NOT EXISTS "DiscountTypes" (
    "DiscountTypeId" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Code" VARCHAR(30) UNIQUE NOT NULL,
    "Name" VARCHAR(100) NOT NULL,
    "DiscountCategory" VARCHAR(30) NOT NULL, -- STATUTORY, PROMOTIONAL, CORPORATE, MANUAL
    "DiscountMethod" VARCHAR(20) NOT NULL, -- PERCENTAGE, FIXED
    "DiscountValue" NUMERIC(18,4) NOT NULL, -- e.g. 20.0000 for 20% or 50.0000 for fixed PHP
    "IsStatutory" BOOLEAN NOT NULL DEFAULT FALSE,
    "RequiresIdentification" BOOLEAN NOT NULL DEFAULT FALSE, -- e.g. SC/PWD ID
    "RequiresApproval" BOOLEAN NOT NULL DEFAULT FALSE,
    "IsActive" BOOLEAN NOT NULL DEFAULT TRUE,
    "CreatedAt" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "CK_DiscountTypes_Code" CHECK (length(btrim("Code")) > 0),
    CONSTRAINT "CK_DiscountTypes_Value" CHECK ("DiscountValue" >= 0)
);

-- Seed standard Philippine statutory and standard discount types
INSERT INTO "DiscountTypes" ("DiscountTypeId", "Code", "Name", "DiscountCategory", "DiscountMethod", "DiscountValue", "IsStatutory", "RequiresIdentification", "RequiresApproval", "IsActive")
VALUES
(1, 'NONE', 'No Discount', 'NONE', 'PERCENTAGE', 0.0000, FALSE, FALSE, FALSE, TRUE),
(2, 'SC', 'Senior Citizen Discount (20%)', 'STATUTORY', 'PERCENTAGE', 20.0000, TRUE, TRUE, FALSE, TRUE),
(3, 'PWD', 'Person with Disability Discount (20%)', 'STATUTORY', 'PERCENTAGE', 20.0000, TRUE, TRUE, FALSE, TRUE),
(4, 'BNPC', 'Basic Necessities & Prime Commodities (5%)', 'STATUTORY', 'PERCENTAGE', 5.0000, TRUE, TRUE, FALSE, TRUE),
(5, 'PROMO', 'Promotional Discount', 'PROMOTIONAL', 'PERCENTAGE', 0.0000, FALSE, FALSE, FALSE, TRUE),
(6, 'EMPLOYEE', 'Employee Discount', 'CORPORATE', 'PERCENTAGE', 10.0000, FALSE, TRUE, TRUE, TRUE),
(7, 'MANUAL', 'Manual Custom Discount', 'MANUAL', 'PERCENTAGE', 0.0000, FALSE, FALSE, TRUE, TRUE)
ON CONFLICT ("Code") DO UPDATE 
SET "Name" = EXCLUDED."Name", "DiscountValue" = EXCLUDED."DiscountValue", "IsStatutory" = EXCLUDED."IsStatutory";

SELECT setval(pg_get_serial_sequence('"DiscountTypes"', 'DiscountTypeId'), coalesce(max("DiscountTypeId"), 1), true) FROM "DiscountTypes";

-- 2. Enhance Orders table with historical discount snapshot fields
ALTER TABLE "Orders"
    ADD COLUMN IF NOT EXISTS "DiscountTypeId" INT NULL REFERENCES "DiscountTypes"("DiscountTypeId"),
    ADD COLUMN IF NOT EXISTS "DiscountCode" VARCHAR(30) NULL,
    ADD COLUMN IF NOT EXISTS "DiscountName" VARCHAR(100) NULL,
    ADD COLUMN IF NOT EXISTS "DiscountPercentage" NUMERIC(5,2) NOT NULL DEFAULT 0.00,
    ADD COLUMN IF NOT EXISTS "CustomerCardNumber" VARCHAR(50) NULL, -- SC/PWD ID Number
    ADD COLUMN IF NOT EXISTS "VatableSales" NUMERIC(18,2) NOT NULL DEFAULT 0.00,
    ADD COLUMN IF NOT EXISTS "VatExemptSales" NUMERIC(18,2) NOT NULL DEFAULT 0.00,
    ADD COLUMN IF NOT EXISTS "ZeroRatedSales" NUMERIC(18,2) NOT NULL DEFAULT 0.00,
    ADD COLUMN IF NOT EXISTS "VatAmount" NUMERIC(18,2) NOT NULL DEFAULT 0.00;

-- 3. Enhance OrderItems table with item-level VAT/discount snapshot fields
ALTER TABLE "OrderItems"
    ADD COLUMN IF NOT EXISTS "DiscountAmount" NUMERIC(18,2) NOT NULL DEFAULT 0.00,
    ADD COLUMN IF NOT EXISTS "VatType" VARCHAR(20) NOT NULL DEFAULT 'VATABLE', -- VATABLE, EXEMPT, ZERO_RATED
    ADD COLUMN IF NOT EXISTS "VatAmount" NUMERIC(18,2) NOT NULL DEFAULT 0.00;

-- 4. Discount Audit Logs for security and accountability
CREATE TABLE IF NOT EXISTS "DiscountAuditLogs" (
    "AuditId" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "OrderId" BIGINT NULL,
    "CashierId" VARCHAR(450) NOT NULL,
    "DiscountCode" VARCHAR(30) NOT NULL,
    "Action" VARCHAR(30) NOT NULL, -- APPLIED, MODIFIED, REMOVED, APPROVED
    "CustomerCardNumber" VARCHAR(50) NULL,
    "DiscountAmount" NUMERIC(18,2) NOT NULL,
    "Reason" VARCHAR(255) NULL,
    "CreatedAt" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_DiscountAuditLogs_Orders" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("OrderId") ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS "IX_DiscountAuditLogs_OrderId" ON "DiscountAuditLogs" ("OrderId");
CREATE INDEX IF NOT EXISTS "IX_DiscountAuditLogs_CashierId" ON "DiscountAuditLogs" ("CashierId");

COMMIT;
